const data = $input.first().json;
const code = data.code ?? data.body?.code ?? '';
const findings = [];
const lines = code.split('\n');
function add(rule,severity,line,title,recommendation){findings.push({agent:'Bug Analysis',rule,severity,line,title,recommendation});}
lines.forEach((s,i)=>{
 const n=i+1;
 if (/^\s*def\s+\w+\([^)]*=\s*(\[\]|\{\}|set\(\))/.test(s)) add('BUG-MUTABLE-DEFAULT','HIGH',n,'Mutable default argument','Use None and create a new collection inside the function.');
 if (/\breturn\s+\w+\s*\/\s*\w+/.test(s)) add('BUG-DIVZERO','MEDIUM',n,'Potential division by zero','Validate the divisor and test zero-count behavior.');
 if (/^\s*except\s*:/.test(s)) add('BUG-BARE-EXCEPT','MEDIUM',n,'Bare except clause','Catch specific exceptions and preserve error details.');
 if (/\bconn\s*=\s*sqlite3\.connect\(/.test(s) && !/with\s+/.test(s)) add('BUG-CONNECTION','LOW',n,'Database connection lifecycle','Close database connections reliably using try/finally or a suitable context manager.');
});
return [{json:{sample_id:data.sample_id,bug_findings:findings}}];

const data = $input.first().json;
const code = data.code ?? data.body?.code ?? '';
const findings=[];
const lines=code.split('\n');
function add(rule,severity,line,title,recommendation){findings.push({agent:'Security Analysis',rule,severity,line,title,recommendation});}
lines.forEach((s,i)=>{
 const n=i+1;
 if (/\b(query|sql)\s*=\s*.*\b(SELECT|UPDATE|INSERT|DELETE)\b.*(?:\+|\.format\s*\(|%\s*\(|f["'])/i.test(s) || /\bexecute(?:many)?\s*\(\s*(?:f["']|[^\n]*\+)/.test(s)) add('SEC-SQL-INJECTION','CRITICAL',n,'Potential SQL injection','Use parameterized queries and bind untrusted values as parameters.');
 if (/\bshell\s*=\s*True\b|\bos\.system\s*\(/.test(s)) add('SEC-SHELL','HIGH',n,'Shell command execution','Use subprocess argument arrays with shell=False and validate inputs.');
 if (/\bpickle\.(?:loads|load)\s*\(/.test(s)) add('SEC-PICKLE','HIGH',n,'Unsafe deserialization risk','Do not unpickle untrusted data; use a constrained data format such as JSON.');
 if (/\b(?:eval|exec)\s*\(/.test(s)) add('SEC-EVAL','CRITICAL',n,'Dynamic evaluation of input','Remove eval/exec and explicitly parse expected data types.');
 if (/\b(?:password|api_key|secret|token)\s*=\s*["'][^"']{6,}["']/.test(s) && !/example|placeholder|dummy/i.test(s)) add('SEC-HARDCODED-SECRET','HIGH',n,'Possible hardcoded credential','Use a secrets manager or environment variables.');
});
return [{json:{sample_id:data.sample_id,agent:'security',findings}}];

const data=$input.first().json;
const code=data.code ?? data.body?.code ?? '';
const tests=String(data.tests ?? '');
const findings=[];
function add(rule,title,recommendation){findings.push({agent:'Test Coverage',rule,severity:'MEDIUM',title,recommendation});}
if(!tests.trim()) add('TEST-NONE','No tests provided','Add unit tests for normal, error, and boundary cases.');
if(/\b(?:discounts|items)\s*=\s*\[\]/.test(code)) add('TEST-MUTABLE','Missing mutable-default regression test','Test repeated calls and isolation of mutable state.');
if(/\breturn\s+\w+\s*\/\s*\w+/.test(code)) add('TEST-ZERO','Missing zero-divisor test','Test division with zero as divisor.');
if(/\b(?:SELECT|execute\s*\()/.test(code)) add('TEST-SQL','Missing SQL input safety test','Test unusual and untrusted query parameters with a temporary database.');
if(/\bshell\s*=\s*True\b|\bpickle\.loads\s*\(|\beval\s*\(/.test(code)) add('TEST-SECURITY','Missing dangerous-input regression tests','Test rejection of untrusted commands, serialized data, and expressions without executing unsafe payloads.');
return [{json:{sample_id:data.sample_id,test_findings:findings}}];

const items=$input.all();
const findings=[];
for(const item of items){for(const key of ['bug_findings','security_findings','test_findings','findings']){if(Array.isArray(item.json[key])) findings.push(...item.json[key]);}}
const rank={CRITICAL:4,HIGH:3,MEDIUM:2,LOW:1};
const unique=new Map();
for(const f of findings){const severity=String(f.severity??'LOW').toUpperCase();const normalized={...f,severity};const id=f.rule ? `${f.rule}|${f.line??''}` : `${f.agent??''}|${f.title??f.issue??''}|${f.line??''}`;if(!unique.has(id))unique.set(id,normalized);}
const prioritized=[...unique.values()].sort((a,b)=>(rank[b.severity]??0)-(rank[a.severity]??0));
const summary={critical:0,high:0,medium:0,low:0,total:prioritized.length};
for(const f of prioritized){const k=f.severity.toLowerCase();if(k in summary && k!=='total')summary[k]++;}
return [{json:{sample_id:items.find(i=>i.json.sample_id)?.json.sample_id??'unknown',status:summary.critical||summary.high?'CHANGES_REQUIRED':'REVIEW_COMPLETE',summary,findings:prioritized,debug:{received_items:items.length,findings_collected:findings.length,findings_after_deduplication:prioritized.length}}}];
